// Checks CSS animations on the anim app (rt-test/anim, generated by
// plan2cpp). First the C++ sampler against Exact's motion crate: every sample
// in anim/reference.h, for every animation value in the app's table. Then the
// app on a 200 × 200 display with a manual clock: what each node paints as
// time moves (a color with each kind of timing function, a fade, a paused
// animation, a fill before a delay, a translate that starts again after
// `none`), and the log line for a value made at run time. Prints each
// failure; exit 0 when all pass.
#include <cmath>
#include <cstdio>
#include <cstring>
#include <string>
#include <vector>

#include "exact_rt.h"
#include "reference.h"
#include "rt_animation.h"

namespace app {
extern const rt::App kApp;
}

namespace {

constexpr int kSize = 200;

// RGB565 pixels in memory, little-endian, the whole screen one band. Drawing
// stays inside the area begun last, as a board's band does.
class Screen : public rt::Display {
 public:
  std::vector<uint16_t> px = std::vector<uint16_t>(kSize * kSize, 0);
  rt::Rect area{0, 0, kSize, kSize};

  bool begin() override { return true; }
  int width() const override { return kSize; }
  int height() const override { return kSize; }
  int band_rows() const override { return kSize; }
  void begin_area(rt::Rect r) override { area = r; }
  void push_area() override {}
  void fill_rect(rt::Rect r, uint32_t rgb) override {
    for (int y = std::max(area.y, r.y); y < std::min(area.y + area.h, r.y + r.h); ++y) {
      for (int x = std::max(area.x, r.x); x < std::min(area.x + area.w, r.x + r.w); ++x) px[y * kSize + x] = to565(rgb);
    }
  }
  int face(float, int) const override { return 0; }
  int text_width(int, const char* text) const override { return 6 * static_cast<int>(std::strlen(text)); }
  int line_height(int) const override { return 10; }
  uint32_t text_rgb = 0x123456;  // the color of the text drawn last
  void draw_text(int, const char*, int, int, uint32_t rgb) override { text_rgb = rgb; }
  uint16_t* row(int y) override { return &px[y * kSize]; }

  static uint16_t to565(uint32_t rgb) {
    return static_cast<uint16_t>(((rgb >> 8) & 0xf800) | ((rgb >> 5) & 0x07e0) | ((rgb >> 3) & 0x001f));
  }
  uint16_t at(int x, int y) const { return px[y * kSize + x]; }
};

class Clocked : public rt::Board {
 public:
  Screen screen;
  int64_t us = 0;
  int64_t micros() const override { return us; }
  rt::Display* display() override { return &screen; }
  bool advance_us(int64_t step) override {
    us += step;
    return true;
  }
};

int failures = 0;

void expect(bool ok, const std::string& what) {
  if (!ok) {
    ++failures;
    std::printf("FAIL %s\n", what.c_str());
  }
}

int value_index(const char* text) {
  for (uint16_t i = 0; i < app::kApp.animation_value_count; ++i) {
    if (std::strcmp(app::kApp.animation_values[i].text, text) == 0) return i;
  }
  return -1;
}

const rt::Animation& animation(int value, int k) {
  return app::kApp.animations[app::kApp.animation_values[value].start + k];
}

// The underlying value reference.h samples over.
rt::AValue underlying(rt::AP prop) {
  rt::AValue v;
  if (prop == rt::AP::Opacity) v.v[0] = 1;
  else if (prop != rt::AP::Translate) v = rt::color_value(0xffffffff);
  return v;
}

void check_reference() {
  int checked = 0;
  for (const reference::Sample& s : reference::kSamples) {
    rt::AValue out;
    const bool has = rt::sample(app::kApp, animation(s.value, s.animation), s.t_ms, s.prop, underlying(s.prop), out);
    const std::string at = std::string(app::kApp.animation_values[s.value].text) + " at " + std::to_string(s.t_ms) + " ms";
    expect(has == s.has, at + ": has an effect " + (has ? "true" : "false"));
    for (int c = 0; has && s.has && c < 4; ++c) {
      expect(std::fabs(out.v[c] - s.v[c]) < 1e-9, at + ": component " + std::to_string(c) + " is " + std::to_string(out.v[c]) + ", Exact's " + std::to_string(s.v[c]));
    }
    ++checked;
  }
  expect(checked > 0, "reference.h has samples");
}

// The reference sample of `text`'s first animation at `t_ms`, as a color.
uint16_t reference_color(const char* text, double t_ms) {
  const int v = value_index(text);
  for (const reference::Sample& s : reference::kSamples) {
    if (s.value != v || s.animation != 0 || s.t_ms != t_ms || s.prop != rt::AP::BackgroundColor) continue;
    rt::AValue c;
    for (int k = 0; k < 4; ++k) c.v[k] = s.v[k];
    return Screen::to565(static_cast<uint32_t>(rt::color_argb(c) & 0xffffff));
  }
  expect(false, std::string("no reference for ") + text + " at " + std::to_string(t_ms));
  return 0;
}

// The reference translate of `text` at `t_ms`, rounded as the view moves a box.
void reference_offset(const char* text, double t_ms, int& dx, int& dy) {
  const int v = value_index(text);
  for (const reference::Sample& s : reference::kSamples) {
    if (s.value != v || s.t_ms != t_ms || s.prop != rt::AP::Translate) continue;
    dx = static_cast<int>(std::lround(s.v[0]));
    dy = static_cast<int>(std::lround(s.v[1]));
    return;
  }
  expect(false, std::string("no translate reference for ") + text + " at " + std::to_string(t_ms));
}

constexpr uint16_t kBlack = 0, kWhite = 0xffff, kGreen = 0x07e0, kRed = 0xf800;

std::string hex(uint16_t v) {
  char b[8];
  std::snprintf(b, sizeof b, "%04x", v);
  return b;
}

void expect_pixel(const Clocked& board, int x, int y, uint16_t want, const std::string& what) {
  const uint16_t got = board.screen.at(x, y);
  expect(got == want, what + ": pixel (" + std::to_string(x) + ", " + std::to_string(y) + ") is " + hex(got) + ", expected " + hex(want));
}

const char* const kSlide = "slide 1s cubic-bezier(0.2, 0.8, 0.2, 1) infinite alternate";

void check_painting() {
  Clocked board;
  rt::Runtime runtime(app::kApp, board, {});
  expect(runtime.boot(), "boot");
  auto at = [&](double ms) {
    board.us = static_cast<int64_t>(ms * 1000);
    runtime.tick();
  };
  at(0);
  expect_pixel(board, 10, 10, reference_color("tint 1s ease-in-out", 0), "tint at 0 ms");
  expect_pixel(board, 50, 10, kBlack, "fade at 0 ms is transparent");
  const uint16_t held = reference_color("tint 1s linear -250ms paused", 0);
  expect_pixel(board, 90, 10, held, "paused at 0 ms");
  at(100);
  expect_pixel(board, 130, 10, kRed, "steps fills backwards before its delay");
  at(500);
  expect_pixel(board, 10, 10, reference_color("tint 1s ease-in-out", 500), "tint at 500 ms");
  const uint16_t half = board.screen.at(50, 10);
  expect(half != kBlack && half != kWhite, "fade at 500 ms is partway: " + hex(half));
  expect_pixel(board, 90, 10, held, "paused at 500 ms holds");
  rt::AValue red = rt::color_value(0xffff0000), green = rt::color_value(0xff00ff00), quarter;
  for (int c = 0; c < 4; ++c) quarter.v[c] = red.v[c] + (green.v[c] - red.v[c]) * 0.25;
  expect_pixel(board, 170, 10, Screen::to565(static_cast<uint32_t>(rt::color_argb(quarter) & 0xffffff)),
               "linear() at 500 ms from the node's own color");
  int dx = 0, dy = 0;
  reference_offset(kSlide, 500, dx, dy);
  expect(dx > 0, "slide has moved at 500 ms");
  expect_pixel(board, 10 + dx, 70 + dy, kGreen, "slide's box at 500 ms");
  expect_pixel(board, 1, 61, kBlack, "slide's box left its place at 500 ms");
  at(750);
  expect_pixel(board, 130, 10, reference_color("tint 1s steps(4, jump-end) 200ms backwards", 750), "steps at 750 ms");
  at(1500);
  expect_pixel(board, 10, 10, kWhite, "tint after its end shows the node's own color");
  expect_pixel(board, 50, 10, kWhite, "fade fills forwards");
  expect_pixel(board, 90, 10, held, "paused at 1500 ms holds");

  expect(runtime.tap("toggle"), "tap toggle");
  at(1600);
  expect_pixel(board, 10, 70, kGreen, "slide at `none` is in its place");
  expect_pixel(board, 10, 10, kWhite, "a commit leaves a running animation's start time");
  expect(runtime.tap("toggle"), "tap toggle again");
  at(1600);
  expect_pixel(board, 19, 70, kGreen, "slide starts again at its start");
  expect_pixel(board, 20, 70, kBlack, "slide starts again at its start, not moved");
  at(2100);
  reference_offset(kSlide, 500, dx, dy);
  expect_pixel(board, 10 + dx, 70 + dy, kGreen, "slide 500 ms after it started again");

  const std::string logs = runtime.agent("{\"op\":\"logs\"}");
  expect(logs.find("animation `tint 2s` is not one of the plan's literals") != std::string::npos,
         "a value made at run time is logged: " + logs);
  expect_pixel(board, 10, 130, kWhite, "a value made at run time plays nothing");
}

void check_scheme() {
  Clocked board;
  rt::Runtime runtime(app::kApp, board, {});
  expect(runtime.boot(), "scheme: boot");
  runtime.tick();
  expect(board.screen.text_rgb == 0xffffff, "dark: text the app gives no color is white");
  expect(runtime.agent("{\"op\":\"scheme\"}") == "{\"scheme\":\"dark\"}", "dark is the default");
  expect(runtime.agent("{\"op\":\"scheme\",\"scheme\":\"light\"}") == "{\"scheme\":\"light\"}", "the op sets light");
  runtime.tick();
  expect(board.screen.text_rgb == 0x000000, "light: text the app gives no color is black");
  expect(runtime.stats.damage_px == kSize * kSize, "a new scheme repaints the whole screen");
  expect(runtime.agent("{\"op\":\"scheme\",\"scheme\":\"sepia\"}").find("error") != std::string::npos,
         "an unknown scheme is an error");
  expect(runtime.scheme() == rt::Scheme::Light, "an unknown scheme keeps the scheme");
}

}  // namespace

int main() {
  check_reference();
  check_painting();
  check_scheme();
  std::printf("anim_check: %s\n", failures ? "failures" : "all checks pass");
  return failures ? 1 : 0;
}
